import { enDictionary, zhDictionary } from "@pindou/core"
import type { Locale } from "@pindou/core/i18n/config"

interface PasswordResetEmailOptions {
  /** The complete reset URL generated by Better Auth. */
  url: string
  /** Locale of the page that requested the reset. */
  locale: Locale
}

/** Escape a value before interpolating it into the HTML email body. */
function escapeHtml(value: string): string {
  const escapes: Record<string, string> = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  }
  return value.replace(/[&<>"']/g, (char) => escapes[char] ?? char)
}

/**
 * Build the password-reset email for the requested locale.
 *
 * @param options - Reset URL and target locale.
 * @returns The localized subject, plain-text body, and HTML body.
 */
export function passwordResetEmail({ url, locale }: PasswordResetEmailOptions) {
  const copy = (locale === "zh" ? zhDictionary : enDictionary).emails.passwordReset
  const safeUrl = escapeHtml(url)

  const text = [
    copy.heading,
    "",
    copy.body,
    "",
    url,
    "",
    copy.expiry,
    copy.ignore,
  ].join("\n")

  const html = `<!doctype html>
<html>
  <body style="margin:0;padding:24px;background:#f6f6f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#171717;">
    <div style="max-width:480px;margin:0 auto;padding:24px;background:#ffffff;border:1px solid #e5e5e5;border-radius:12px;">
      <h1 style="margin:0 0 16px;font-size:20px;line-height:1.4;">${copy.heading}</h1>
      <p style="margin:0 0 20px;font-size:14px;line-height:1.6;">${copy.body}</p>
      <p style="margin:0 0 20px;">
        <a href="${safeUrl}" style="display:inline-block;padding:10px 16px;background:#171717;color:#ffffff;text-decoration:none;border-radius:8px;font-size:14px;">${copy.button}</a>
      </p>
      <p style="margin:0 0 8px;font-size:12px;line-height:1.6;color:#666666;">${copy.expiry}</p>
      <p style="margin:0;font-size:12px;line-height:1.6;color:#666666;">${copy.ignore}</p>
    </div>
  </body>
</html>`

  return { subject: copy.subject, text, html }
}
